def backfill_tracking_records(apps, schema_editor):
    Project = apps.get_model('member', 'Project')
    GovernmentAgency = apps.get_model('member', 'GovernmentAgency')
    ProjectBaseline = apps.get_model('member', 'ProjectBaseline')
    IssueResponsePolicy = apps.get_model('member', 'IssueResponsePolicy')
    ReportIssue = apps.get_model('member', 'ReportIssue')

    for project in Project.objects.all().iterator():
        agency_name = (project.implementing_agency or '').strip()
        if agency_name:
            agency, _created = GovernmentAgency.objects.get_or_create(name=agency_name)
            project.agency_id = agency.pk
            project.save(update_fields=['agency'])
        ProjectBaseline.objects.get_or_create(
            project_id=project.pk,
            defaults={
                'approved_budget': project.project_Budgeting,
                'approved_start_date': project.start_date,
                'approved_end_date': project.end_date,
                'approved_by_id': project.created_by_id,
            },
        )

    for severity, target_hours in (
        ('critical', 24),
        ('high', 72),
        ('moderate', 168),
        ('low', 336),
    ):
        IssueResponsePolicy.objects.get_or_create(
            severity=severity,
            defaults={'target_hours': target_hours},
        )

    targets = dict(IssueResponsePolicy.objects.values_list('severity', 'target_hours'))
    for issue in ReportIssue.objects.filter(response_due_at__isnull=True).iterator():
        target_hours = targets.get(issue.severity)
        if target_hours is not None and issue.created_at:
            issue.response_due_at = issue.created_at + timedelta(hours=target_hours)
            issue.save(update_fields=['response_due_at'])


